import {trackableConditions,saveAbilities,ownEndSpells,ownEndTarget,timedConditionEffects,durationSnapshot,maxHoldSeconds} from './lib/srd-condition-lifecycle.mjs';
import {htmlCopy} from './locale.js';
import {spellDiceFields,spellDiceField} from './spell-dice-fields.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options=values=>values.map(n=>`<option>${esc(n)}</option>`).join('');
const confirm=label=>`<label><input type="checkbox" name="confirmed" required>${htmlCopy(label)}</label>`;
function saveHTML(e,play){
 const s=e.save;if(!s)return '';
 const fields=`<input type="hidden" name="id" value="${esc(e.id)}"><input type="hidden" name="attempt" value="${s.attempt}">`;
 const auto=e.turnTarget===ownEndTarget;
 const status=`<p>${esc(s.ability)} · DC ${s.dc} · ${htmlCopy(s.pending?'Save pending':auto&&play.combat?.active?'At end of your turn':'Awaiting confirmed trigger')}</p>${auto?`<p>${htmlCopy(Object.hasOwn(e,'remainingSeconds')?'Remaining duration (confirmed game seconds)':'Automatic own-turn reminder only; the DM tracks spell duration and concentration.')}${Object.hasOwn(e,'remainingSeconds')?': '+e.remainingSeconds:''}</p>`:''}`;
 if(play.dead)return status;
 if(!s.pending&&auto&&play.combat?.active)return status;
 if(!s.pending)return `${status}<form data-play-form="condition-save-queue" class="enc-inline">${fields}${confirm('Confirm the originating effect allows a save now')}<button type="submit">${htmlCopy('Queue save')}</button></form>`;
 if(play.shape?.active)return status+`<p>${htmlCopy('Resolve transformed-character saves with the DM; end the source manually if appropriate.')}</p>`;
 return `${status}<form data-play-form="condition-save-roll" class="enc-inline">${fields}<input type="hidden" name="effectName" value="${esc(e.name)}"><input type="hidden" name="source" value="${esc(e.source)}"><input type="hidden" name="ability" value="${esc(s.ability)}"><input type="hidden" name="dc" value="${s.dc}"><label>${htmlCopy('First d20')}<input type="number" name="first" min="1" max="20"></label><label>${htmlCopy('Second d20 if needed')}<input type="number" name="second" min="1" max="20"></label><p>${htmlCopy('Leave dice blank only for an automatic failure.')}</p><label><input type="checkbox" name="advantage">${htmlCopy('Advantage')}</label><label><input type="checkbox" name="disadvantage">${htmlCopy('Disadvantage')}</label><label>${htmlCopy('Additional modifier')}<input type="number" name="bonus" min="-100" max="100" value="0" required></label>${spellDiceFields(play,'save')}${confirm('I confirmed other applicable effects and the situation with the table.')}<button type="submit">${htmlCopy('Record calculated save')}</button></form>`;
}
function durationHTML(play){
 if(play.dead||!timedConditionEffects(play).length)return '';
 return `<details><summary>${htmlCopy('Advance tracked effect time')}</summary><p>${htmlCopy('Use only DM-confirmed elapsed game time, not real time or an assumed personal turn length. Reconcile all intervening saves first. Expired sources and their obsolete pending saves will be removed; caster Concentration still requires confirmation.')}</p><form data-play-form="condition-time-advance" class="enc-inline"><input type="hidden" name="snapshot" value="${esc(durationSnapshot(play))}"><label>${htmlCopy('Elapsed game seconds')}<input type="number" name="seconds" min="1" max="${maxHoldSeconds}" required></label>${confirm('Confirm elapsed time, ordering and cancellation of obsolete saves with the DM')}<button type="submit">${htmlCopy('Advance tracked effect time')}</button></form></details>`;
}
export function conditionSourcesHTML(play){
 const effects=play.conditionEffects??[];
 return `<div class="play-class-feature"><h3>${htmlCopy('Tracked condition sources')} (${effects.length})</h3><p class="play-note">${htmlCopy('Manual conditions and tracked sources are independent. Confirm each source with the DM; end it only when the originating effect allows. Confirm effect expiry and manual save timing with the DM.')}</p>${effects.map(e=>`<section><form data-play-form="condition-source-remove" class="enc-inline"><p><strong>${esc(e.name)}</strong> · ${esc(e.source)} (${esc(e.id)})</p><input type="hidden" name="id" value="${esc(e.id)}">${confirm('Confirm this source has ended')}<button type="submit" ${play.dead?'disabled':''}>${htmlCopy('Remove source')}</button></form>${Object.hasOwn(e,'expiresOwnTurn')?`<p>${htmlCopy('Expires at end of personal turn')}: ${e.expiresOwnTurn}</p>`:''}${saveHTML(e,play)}</section>`).join('')}${durationHTML(play)}${play.dead?'':`<form data-play-form="condition-source-add" class="enc-inline"><label>${htmlCopy('Condition')}<select name="name">${options(trackableConditions)}</select></label><label>${htmlCopy('Effect source')}<input name="source" maxlength="80" required></label>${confirm('Confirm source with the DM')}<button type="submit">${htmlCopy('Add source')}</button></form><details><summary>${htmlCopy('Add save-ended condition')}</summary><p>${htmlCopy('Use only if a successful repeat save ends this condition source on you. Confirm the rules, DC and timing with the DM.')}</p><form data-play-form="condition-save-add" class="enc-inline"><label>${htmlCopy('Condition')}<select name="name">${options(trackableConditions)}</select></label><label>${htmlCopy('Effect source')}<input name="source" maxlength="80" required></label><label>${htmlCopy('Saving Throw')}<select name="ability">${options(saveAbilities)}</select></label><label>DC<input type="number" name="dc" min="1" max="999" required></label>${confirm('Confirm source with the DM')}<button type="submit">${htmlCopy('Add save-ended condition')}</button></form></details><details><summary>${htmlCopy('Add automatic end-of-turn save')}</summary><p>${htmlCopy('For an active Hold Person or Hold Monster spell after the initial failed save. Confirm the target, DC, and spell with the DM. End my turn queues a Wisdom save; remove the source when the spell ends.')}</p><form data-play-form="condition-turn-save-add" class="enc-inline"><label>${htmlCopy('Effect source')}<select name="spell">${options(ownEndSpells)}</select></label><label>DC<input type="number" name="dc" min="1" max="999" required></label><label>${htmlCopy('Remaining game seconds (optional, 1–60)')}<input type="number" name="remainingSeconds" min="1" max="60"></label>${confirm('Confirm source with the DM')}<button type="submit">${htmlCopy('Add automatic end-of-turn save')}</button></form></details>`}</div>`;
}
const number=(f,k)=>f.get(k)===null||f.get(k)===''?NaN:Number(f.get(k));
export function conditionSourceCommand(type,fields){
 const confirmed=fields.has('confirmed');
 if(type==='condition-turn-save-add')return {type,spell:fields.get('spell'),dc:number(fields,'dc'),confirmed,...(fields.get('remainingSeconds')===null||fields.get('remainingSeconds')===''?{}:{remainingSeconds:number(fields,'remainingSeconds')})};
 if(type==='condition-time-advance')return {type,seconds:number(fields,'seconds'),snapshot:fields.get('snapshot'),confirmed};
 if(type==='condition-source-add')return {type,name:fields.get('name'),source:fields.get('source'),confirmed};
 if(type==='condition-save-add')return {type,name:fields.get('name'),source:fields.get('source'),ability:fields.get('ability'),dc:number(fields,'dc'),confirmed};
 const id=fields.get('id');
 if(type==='condition-save-queue')return {type,id,attempt:number(fields,'attempt'),confirmed};
 if(type==='condition-save-roll')return {type,id,attempt:number(fields,'attempt'),name:fields.get('effectName'),source:fields.get('source'),ability:fields.get('ability'),dc:number(fields,'dc'),rolls:fields.get('second')!==null&&fields.get('second')!==''?[number(fields,'first'),number(fields,'second')]:fields.get('first')!==null&&fields.get('first')!==''?[number(fields,'first')]:[],advantage:fields.has('advantage'),disadvantage:fields.has('disadvantage'),otherBonus:number(fields,'bonus'),confirmed,...spellDiceField(fields)};
 return {type,id,confirmed};
}
